('143f2309-0167-45c4-9a0b-c075f7962844', 'UNPAB Vocal Journey Plaque', 2, 11, 0, 0, '[\"Portfolio of Plaques_693b968583b2c.png\"]', '{\"Material\":\"Acrylic\",\"Color\":\"White\",\"Design\":\"Curved\",\"Size\":\"13 x 18 cm\"}', 'This premium acrylic appreciation plaque features an elegant appearance, used as a token of appreciation for participation in the Vocal Journey event with the theme Voice Power. Packaged in a blue velvet box, this plaque adds a luxurious look and is perfect for speakers, resource persons, or special attendees at a formal event or seminar.', 173, '2025-12-11 21:13:57', '2026-05-04 09:16:14', 0, 'Tidak Aktif', NULL),
